var SID=(function(){try{var k="cb:sid",v=localStorage.getItem(k);if(!v){v=Math.random().toString(36).slice(2,10)+Date.now().toString(36);localStorage.setItem(k,v);}return v;}catch(e){return"anon";}})();var walletA=null,ctxCache={at:0,v:[]};function wallet(){if(walletA||!window.AIL||!window.AIL.wallets||!window.AIL.wallets.silent)return Promise.resolve(walletA);return window.AIL.wallets.silent().then(function(a){walletA=a?String(a).toLowerCase():null;return walletA;}).catch(function(){return null;});}
function withCtx(){return wallet().then(function(a){if(!a||!window.AIL.myPositions)return[];if(Date.now()-ctxCache.at<60000)return ctxCache.v;return Promise.race([window.AIL.myPositions(a),new Promise(function(res){setTimeout(function(){res([]);},5000);})]).then(function(v){ctxCache={at:Date.now(),v:v||[]};return ctxCache.v;});}).catch(function(){return[];});}
wallet();function forward(answer,human){var q=history.filter(function(m){return m.role==="user";}).slice(-1)[0];if(!q)return;try{fetch("/api/chat-log",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({wallet:walletA,q:q.content,a:String(answer||"").slice(0,600),page:location.hash||"/",sid:SID,human:!!human}),keepalive:true}).catch(function(){});}catch(e){}}
var lastReply=0,pollTimer=null;try{lastReply=parseInt(localStorage.getItem("cb:last")||"0",10)||0;}catch(e){}
